    "value > 0.0"
   ]
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from venmo app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "description",
   "type": "string",
   "required": false,
   "description": "Description of or note about the payment request.",
   "default": "",
   "constraints": []
