# Let's search for each old song and find the exact matching song_id
# We'll create a function to find the exact match
def find_song_id(title, artists):
    # Search with the title
    results = apis.spotify.search_songs(query=title, access_token=spotify_token, page_limit=20)
    # Filter results to find exact match
    for song in results:
        if song['title'].strip().lower() == title.strip().lower():
            # Check if all artists match
            song_artists = {a['name'].strip().lower() for a in song['artists']}
            old_artists = {a.strip().lower() for a in artists}
            if song_artists == old_artists:
                return song['song_id']
    return None

