# Verify that all archived songs have been removed from the original playlists and remain in "Old Songs"
all_playlists_after = []
page_index = 0
while True:
    page = apis.spotify.show_playlist_library(access_token=login_result["access_token"], page_index=page_index, page_limit=20)
    if not page:
        break
    all_playlists_after.extend(page)
    if len(page) < 20:
        break
    page_index += 1

# Check each playlist
archived_song_ids = {song_id for song_id, _, _ in song_ids_to_archive}
old_songs_playlist = None
for pl in all_playlists_after:
    if pl["playlist_id"] == 654:
        old_songs_playlist = pl
    else:
        # Check if any archived song remains
        remaining = [sid for sid in pl["song_ids"] if sid in archived_song_ids]
        if remaining:
            print(f"WARNING: Playlist {pl['playlist_id']} ({pl['title']}) still contains archived songs: {remaining}")

# Verify Old Songs playlist contains all archived songs
if old_songs_playlist:
    missing = archived_song_ids - set(old_songs_playlist["song_ids"])
    if missing:
        print(f"WARNING: Old Songs playlist missing archived songs: {missing}")
    else:
        print("All archived songs are present in Old Songs playlist (654).")
else:
    print("ERROR: Old Songs playlist not found.")

print("Verification complete.")

# Fetch details for each song to identify the old songs
song_details = {}
for sid in all_song_ids:
    song = apis.spotify.show_song(song_id=sid, access_token=spotify_login['access_token'])
    song_details[sid] = song
    print(sid, song)

