steps.code:
# Let's fetch all 7 playlists and collect which old songs are in each.
old_song_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}
playlist_ids = [513, 514, 515, 516, 517, 518, 519]
playlist_songs = {}
for pid in playlist_ids:
    pl = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    songs = pl.get('songs', [])
    playlist_songs[pid] = songs
    old_in_pl = [s['id'] for s in songs if s['id'] in old_song_ids]
    print(f"Playlist {pid} ({pl['title']}): {len(songs)} songs, old songs: {old_in_pl}")

