steps.code:
# Define the old song IDs and playlist IDs from history
old_song_ids = {295, 324, 22, 245, 320, 92, 299, 4, 278, 69, 219, 298, 265}
playlist_ids = [513, 514, 515, 516, 517, 518, 519]

# Check each playlist for old songs
found_songs = set()
for pid in playlist_ids:
    playlist = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    print(f"Playlist {pid}: {playlist['title']} - songs: {[s['id'] for s in playlist['songs']]}")
    for song in playlist['songs']:
        if song['id'] in old_song_ids:
            found_songs.add(song['id'])
            print(f"  Found old song: {song['id']} - {song['title']}")

print("Found old songs:", found_songs)

# Remove all old songs from each playlist
removal_pairs = []
for pid in playlist_ids:
    playlist = apis.spotify.show_playlist(playlist_id=pid, access_token=spotify_token)
    for song in playlist['songs']:
        if song['id'] in old_song_ids:
            removal_pairs.append((pid, song['id']))

print("Removal pairs:", removal_pairs)

# Perform removals
for pid, sid in removal_pairs:
    result = apis.spotify.remove_song_from_playlist(playlist_id=pid, song_id=sid, access_token=spotify_token)
    print(f"Removed song {sid} from playlist {pid}: {result}")

