steps.code:
# Search for each TODO song to get release dates
release_dates = {}
for song in todo_info:
    query = f"{song['title']} {song['artist']}"
    result = apis.spotify.search_songs(query=query, access_token=spotify_token, page_limit=5)
    # Find the matching song
    found = None
    for s in result:
        if s['title'].lower() == song['title'].lower():
            # Check if artist matches
            artists = [a['name'].lower() for a in s['artists']]
            if song['artist'].lower() in artists:
                found = s
                break
    if found:
        release_dates[song['title']] = found['release_date']
        print(f"{song['title']}: {found['release_date']}")
    else:
        print(f"NOT FOUND: {song['title']}")

